    check('atmosphere/vessel and all voyage schedule fields unchanged',b['vessel'] == before['arcs'][1]['vessel'] and all(v == before['arcs'][1]['route'][key] for key,v in b['route'].items() if key!='outbound'))
    check('five actual cash pools conserve initial stock',sum(x['goldCoins'] for x in d['common']['moneyCustody']['initialPools'])==421 and sum(Fraction(x['goldCoins'],50) for x in d['common']['moneyCustody']['initialPools'])==Fraction(421,50))
    check('wages exactly two equal split sorties and no third',40-2*(10+10)==0)
    check('three stable spindle offers exhaust only six coins',3*2==6)
    check('advance payload counts actual twenty gold coins once',Fraction(1217)+Fraction(20,50)==Fraction('1217.4') and Fraction('65.3')+Fraction(20,500)==Fraction('65.34'))
    check('six sheets and impressions permit two complete three-plate sets',6//3==2 and 6-2*3==0)
    check('printed service fits ten minutes even with charged vent wait',4*6+60+3*6+120+3*6+60 < 600)
    check('updated existing refusal examples retain IDs with actual ten-minute discussion',lookup['ARC17-C03']['elapsedSeconds']==lookup['ARC17-C07']['elapsedSeconds']==600)
    check('all approval gates remain false',not any(d['common']['approvalGates'].values()))
    for row in sources: check('source unchanged: '+row['path'],info(G/row['path'])==row)
    failures = [x for x in checks if not x['pass']]; assert not failures, failures
    history.mkdir(parents=True)
    for name in ['ARCS_MODEL.json','CASEBOOK.json','MANIFEST.json']:(history/name).write_bytes((root/name).read_bytes())
    (root/'ARCS_MODEL.json').write_bytes(encoded(d)); (root/'CASEBOOK.json').write_bytes(encoded(cb))
    entries = [{'path':p.relative_to(root).as_posix(),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(root.rglob('*')) if p.is_file() and p!=root/'MANIFEST.json']
    (root/'MANIFEST.json').write_bytes(encoded({'files':entries}))
    receipt.write_bytes(encoded({
        'recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'NEW local proposals; not submitted, jointly reviewed, adopted or playtested.',
        'previousModel':info(history/'ARCS_MODEL.json'),'previousCases':info(history/'CASEBOOK.json'),'model':info(root/'ARCS_MODEL.json'),'casebook':info(root/'CASEBOOK.json'),
        'weightSource':d['common']['moneyCustody']['weightSource'],
        'originalSourceBoundary':'OriginalCosmology paragraphs319–322 establish post-epilogue hooks, not the new named treasurers, salaries, press, stock, patent permissions or stakeholder choice. Those are provisional adaptation authorship.',
        'changes':[{'field':'/'+k,'before':before.get(k),'after':v} for k,v in d.items() if before.get(k)!=v],
        'authoredCases':65,'newCases':14,'retainedPriorCaseIds':51,'modifiedPriorCases':['ARC17-C03','ARC17-C07'],
        'checks':checks,'checkCount':len(checks),'failureCount':0,
        'scope':'Preservation of supplied sources, earlier case IDs, existing annual contract states and voyage/environment procedures; finite stock and selected arithmetic. Not a gameplay engine, exhaustive semantics, balance assessment or human test.',
        'proposedResolutions':['ARC03-12','ARC03-15'],
        'remaining':['Actual GPT semantic challenge and disposition of all arc proposals','EPI15 hostility/time/source-language pass','EPI08–14 exact return recovery and semantic integration','Player/Director prose after semantic review','Owner campaign frame before activation'],
        'newRulesAdopted':False,'sourceInformationDeleted':0,'campaignEpochChosen':False,'runtimeTestsExecuted':0,'humanPlaytested':False
    }))
    print(json.dumps({'receipt':info(receipt),'model':info(root/'ARCS_MODEL.json'),'casebook':info(root/'CASEBOOK.json'),'cases':65,'checks':len(checks),'failures':0,'newRulesAdopted':False}))

